quests[53264] = { id = 53264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Großmeerwels", progress = "Ein Bauch voll Fisch ist einfach ein wunderbares Gefühl.", completion = "Ihr seid sehr großzügig, {name}. Vielen Dank." }
quests[53265] = { id = 53265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Gold", description = "Wir haben viel Zeit und Ressourcen darauf verwendet, uns auf den bevorstehenden Kampf vorzubereiten. \n\nIm Zuge der letzten Vorbereitungen werden wir zusätzliche Mittel bereitstellen, damit weitere Ausbildung und Nachschublieferungen auch kurzfristig verfügbar sind.\n\nMöchtet auch Ihr etwas spenden?", sourceObjective = "Spendet 1000000 Gold an Zahlmeister Vauldren im Hafen von Boralus.", progress = "Im Zuge der letzten Vorbereitungen werden wir zusätzliche Mittel bereitstellen, damit weitere Ausbildung und Nachschublieferungen auch kurzfristig verfügbar sind.\n\nMöchtet auch Ihr etwas spenden?", completion = "Wie großzügig von Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[53266] = { id = 53266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blühende Meeresstängel" }
quests[53267] = { id = 53267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missionsbericht: Dinosaurierforschung", description = "Eure Anhänger haben Euch einen Bericht über die Mission in der Tiefgrünen Höhle geschickt.\n\nDarin steht, dass die Mission ein Erfolg war und eine Reihe von Dinosaurierexemplaren geborgen werden konnte.\n\nBringt den Bericht zu Hochkommandant Wyrmbann an Bord der Erlösenden Winde.", sourceObjective = "Bringt den Missionsbericht zu Halford Wyrmbann.", progress = "Gibt es Neuigkeiten über die Mission in der Tiefgrünen Höhle?", completion = "Die Mission scheint ein Erfolg gewesen zu sein. Gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[53268] = { id = 53268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dinosaurierforschung", description = "Die Mission zur Sammlung von Forschungsexemplaren war ein voller Erfolg. Gut gemacht, {name}.\n\nIhr solltet beim Kommandanten des Außenpostens vorsprechen und die Exemplare persönlich inspizieren.\n\nMacht Euch auf zur Tiefgrünen Höhle in Zuldazar und sprecht mit Argrim Felstief.", sourceObjective = "Sprecht mit Argrim Felstief.", completion = "Euer Team hat seine Arbeit gut gemacht! Seht Euch bloß all diese winzigen Dinosaurier an... Es gibt mehr von ihnen als von uns!", sourceObjectiveStatus = "unverified-source-field" }
