quests[53275] = { id = 53275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missionsbericht: Ersatzteile", description = "Eure Anhänger haben Euch einen Bericht über die Mission zur Sammlung von Bergungsgut für den Mugambarundblick geschickt.\n\nDarin steht, dass die Mission ein Erfolg war und die benötigten Materialien gesammelt werden konnten.\n\nBringt den Bericht zu Hochkommandant Wyrmbann an Bord der Erlösenden Winde.", sourceObjective = "Bringt den Missionsbericht zu Halford Wyrmbann.", progress = "Gibt es Neuigkeiten über die Mission am Mugambarundblick?", completion = "Die Mission scheint ein Erfolg gewesen zu sein. Gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[53276] = { id = 53276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ersatzteile", description = "Ein Ingenieur wurde am Mugambarundblick stationiert, um eine Verschrottungsmaschine zu konstruieren.\n\nDie Mission zur Bergung von Material für die Maschine war dank Eurer Führung ein voller Erfolg.\n\nMacht Euch auf den Weg zum Mugambarundblick in Zuldazar und trefft Euch mit Giblin Funkenuhr. Er hat den Ausbau des Außenpostens überwacht.", sourceObjective = "Sprecht mit Giblin Funkenuhr.", completion = "Diese Maschine zerlegt einfach alles! Los, probiert es nur!", sourceObjectiveStatus = "unverified-source-field" }
