quests[53295] = { id = 53295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leistet Euren Beitrag", description = "Den B-b-barbier? Bitte was? Ihr möchtet wissen, wo hier ein Barbier ist?\n\nAber entschuldigt mal, {race}, merkt Ihr nicht, dass hier gerade ein K-R-I-E-G im Gange ist?\n\nUnd überhaupt, was habt Ihr eigentlich in letzter Zeit für die Allianz getan? Raus da mit Euch! Legt ein paar von der Horde um oder ich werde Euch persönlich den Schädel rasieren!", sourceObjective = "Aktiviert den Kriegsmodus und tötet 1 Spielercharakter der Horde in der Welt.", completion = "Das wär's, {class}. Gute Arbeit. \n\nAber ich habe keine Ahnung, wo wir hier den Barbier finden sollen. Das ist das reinste Labyrinth hier!", sourceObjectiveStatus = "unverified-source-field" }
