quests[53306] = { id = 53306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missionsbericht: Dschungeleskorte", description = "Eure Anhänger haben Euch einen Bericht über die Eskortenmission zum Nebelschlingenvorsprung geschickt.\n\nDarin steht, dass die Mission ein Erfolg war und die Verstärkung sicher ihren Bestimmungsort erreicht hat.\n\nBringt den Bericht zu Hochkommandant Wyrmbann an Bord der Erlösenden Winde.", sourceObjective = "Bringt den Missionsbericht zu Halford Wyrmbann.", progress = "Gibt es Neuigkeiten über die Mission zum Nebelschlingenvorsprung?", completion = "Die Mission scheint ein Erfolg gewesen zu sein. Gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[53307] = { id = 53307, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dschungeleskorte", description = "Am Nebelschlingenvorsprung sind jetzt Heiler stationiert.\n\nDie Mission, die Verstärkung durch den Dschungel zu eskortieren, war dank Eurer Führungskraft ein voller Erfolg.\n\nMacht Euch auf zum Nebelschlingenvorsprung in Zuldazar und trefft Euch dort mit der Kommandantin des Außenpostens, um sicherzustellen, dass sie alles hat, was sie braucht.", sourceObjective = "Sprecht mit Neva.", completion = "Dank Euch kann der Außenposten jetzt zusätzlich zu den regulären Dienstleistungen auch Unterstützung durch Heilung anbieten.", sourceObjectiveStatus = "unverified-source-field" }
