quests[53329] = { id = 53329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plastisches Platin" }
quests[53330] = { id = 53330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Klingenklauenalpha", description = "Die Horde benötigt Euren Beitrag!\n\nWir haben Bedarf an Materialien für die Herstellung und Reparatur unserer Waffen und Rüstungen.\n\nDieses Land birgt eine Fülle von Ressourcen, und wir allein haben ein Anrecht auf sie.\n\nErlegt den größten Wolf, den Ihr finden könnt, und nehmt Euch seinen Pelz, damit wir einen Umhang fertigen können, der Rexxars würdig ist!\n\n- Zenturio Kaga Warmstein", sourceObjective = "Beschafft einen Klingenklauenalphapelz.", progress = "Habt Ihr einen geeigneten Pelz finden können?", completion = "Ein exquisiter Pelz! Gute Arbeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[53331] = { id = 53331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meisterleistung" }
quests[53332] = { id = 53332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit für Krieg", description = "Kehrt zu Kommandant Wyrmbann zurück, um mit der 7. Legion zusammenzuarbeiten.", sourceObjective = "Meldet Euch bei Halford Wyrmbann in Boralus.", completion = "<Halford sieht sich die gesammelten Ressourcen an.>\n\nDas sollte reichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53333] = { id = 53333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit für Krieg", description = "Kehrt zu Nathanos Pestrufer zurück, um mit den Eidgebundenen zusammenzuarbeiten.", sourceObjective = "Meldet Euch bei Nathanos Pestrufer in Zuldazar.", completion = "<Nathanos sieht sich die gesammelten Ressourcen an.>\n\nDas sollte reichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53334] = { id = 53334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Kriegsressourcen", progress = "Wir sind Teil einer großen Anstrengung. Lasst uns in der kommenden Schlacht gemeinsam kämpfen.", completion = "Habt Dank für Euren Beitrag." }
quests[53335] = { id = 53335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Kriegsressourcen", progress = "Unsere Streitkräfte sammeln sich für die bevorstehende Schlacht. Möchtet Ihr unsere Anstrengungen weiter unterstützen?", completion = "Eine großzügige Spende. Ich werde den Kommandanten von Eurem Beitrag unterrichten." }
quests[53336] = { id = 53336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Kaiserin der Säbelhauer", description = "An jeden und alle, die mutig genug sind, eine Herausforderung zu suchen: \n\nFindet und besiegt eine wilde Kaiserin der Säbelhauer, die stärkste und wildeste aller Säbelhauer in Zuldazar.\n\nMan findet sie entlang der Straße, die vom Lianendorf wegführt.\n\nJeder, der Erfolg hat, erhält eine Belohnung!", sourceObjective = "Tötet eine Kaiserin der Säbelhauer.", completion = "Danke, Champion. 'ne Bedrohung weniger für diese Gegend.", sourceObjectiveStatus = "unverified-source-field" }
quests[53337] = { id = 53337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Alpha der Eisenknöchel", description = "An jeden und alle, die mutig genug sind, eine Herausforderung zu suchen:\n\nFindet und besiegt einen Alpha der Eisenknöchel, den größten und gefährlichsten aller wilden Gorillas.\n\nMan findet sie entlang der Straße, die vom Lianendorf wegführt.\n\nJeder, der Erfolg hat, erhält eine Belohnung!", sourceObjective = "Tötet einen Alpha der Eisenknöchel.", completion = "Ihr habt diesen Eisenknöchel aus dem Weg geräumt? Das bedeutet uns eine Menge. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[53338] = { id = 53338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beweist Euren Wert", description = "Habt Ihr draußen viele Truppen der Allianz gesichtet, {race}? Berichten zufolge scheint sich die Präsenz der Allianz hier auf Zandalar zusehends zu verstärken.\n\nVergesst nicht, wir befinden uns im K-R-I-E-G. Beweist Euren Wert und legt da draußen so viele von ihnen um wie möglich.\n\nFür die Horde!", sourceObjective = "Aktiviert den Kriegsmodus und tötet 1 Spielercharakter der Allianz in der Welt.", completion = "Das ist ein guter Anfang. Hier ist etwas von unseren Ingenieuren, das sich als nützlich erweisen könnte...", sourceObjectiveStatus = "unverified-source-field" }
quests[53339] = { id = 53339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFG  - BFA - Island Expedition - Heroic Win - Nth" }
quests[53340] = { id = 53340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFG  - BFA - Island Expedition - Mythic Win - Nth" }
quests[53341] = { id = 53341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFG  - BFA - Island Expedition - PvP Win - Nth" }
quests[53342] = { id = 53342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Geschmolzene Kern", description = "Wir brauchen ein Fragment des Kerns, um den Schwarzen Amboss zu reparieren, und dann noch wer weiß wie viel Dunkeleisen, um die notwendige Reinheit zu erreichen. Das kann Thaelin ausrechnen.\n\nEhrlich gesagt, glaube ich, dass er mit Euch gehen sollte, wenn Ihr ein Fragment des Geschmolzen Kerns besorgt.\n\nEs ist zu gefährlich, mit der Maulwurfmaschine zu tief zu graben, aber Thaelin hat einen robusten Panzer, mit dem Ihr den Rest des Wegs sicher hinter Euch bringen könnt.\n\nSprecht mich an, wenn Ihr bereit seid.", sourceObjective = "Sprecht mit Moira an der Botschaft von Sturmwind, um zum Geschmolzenen Kern zu reisen und ein Fragment des Geschmolzenen Kerns zu besorgen.", progress = "Manchmal ist es schwer, Thaelins Geschwafel zu verstehen, aber er hat wirklich Köpfchen.", completion = "Gute Arbeit, {name}. Das Fragment wird uns bei der Reparatur des Schwarzen Ambosses ein gutes Stück voranbringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53343] = { id = 53343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwingen lassen" }
quests[53344] = { id = 53344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bildersturm" }
quests[53345] = { id = 53345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plünderung und Vorräte" }
quests[53346] = { id = 53346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troggtrampeln" }
quests[53347] = { id = 53347, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hummelbummel will sich tummeln", sourceObjective = "Spürt Raimunds Geheimzutat auf.", progress = "Konntet Ihr sie finden? Ich glaube, sie ist in einer lila Flasche.", completion = "Ja! Das ist genau das, was wir brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53348] = { id = 53348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Donnerschnauze", description = "Die Ebermatriarchin Donnerschnauze ist die größte ihrer Art im Tal. Sie stellt eine ernsthafte Bedrohung für unsere Truppenbewegungen im Süden dar.\n\nAus diesem Grund hat Zenturio Kaga Warmstein ein Kopfgeld auf sie ausgesetzt. Man muss ihr nur einen Beweis bringen, dass sie tot ist.\n\nDonnerschnauze soll in der Nähe des Krals der Borstenrücken zu finden sein, also haltet nach Stachelebern Ausschau!", sourceObjective = "Bringt Donnerschnauzes Schnauze zu Zenturio Kaga Warmstein.", progress = "Ja?", completion = "Mit dem Tod der Matriarchin wird sich die nächste Generation Eber verzögern. Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[53349] = { id = 53349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eroberungsbelohnung", sourceObjective = "Eure Kühnheit auf dem Schlachtfeld ist ohnegleichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53351] = { id = 53351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das RIESENFLÖZ!!: Eisenfeind", description = "Mogul Ratztunk war schon immer ein Neidhammel und wünschte, er wäre Gallywix oder noch besser.\n\nAber er ist ein ganz übler Gierschlund. Er schreckt vor nichts zurück, um seine Ziele zu erreichen, koste es, was es wolle.\n\nSelbst für ihn war es dreist, uns hier in den Schwarzfelstiefen anzugreifen.\n\nEr hätte wissen müssen, dass er damit zu weit geht. Tötet diesen habgierigen Schuft und bringt den Hammer dorthin zurück, wo er hingehört.\n\nIhr findet ihn in Kezan an einem Ort, den er \"Das Riesenflöz\" nennt, wahrscheinlich mit viel zu vielen Ausrufezeichen.", sourceObjective = "Holt Eisenfeind von Mogul Ratztunk zurück.", progress = "Ich wünschte, ich hätte seinen Gesichtsausdruck sehen können, als Ihr ihm den Hammer aus den kalten Händen gerissen habt.", completion = "Geschieht ihm recht. Immerhin hat er eines unserer heiligsten Artefakte gestohlen. Ich hoffe, er hat sich gewunden.", sourceObjectiveStatus = "unverified-source-field" }
quests[53352] = { id = 53352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Feuerlande", description = "In Ordnung, das war der schwere Teil, {name}.\n\nAlso, wir müssen jetzt nur noch das Fragment des Geschmolzenen Kerns, das Ihr gefunden habt, in die Feuerlande bringen und in Ragnaros' alter Badewanne heißmachen.\n\nMacht Euch keine Sorgen! Ich stelle Euch Ambossthan Thurgaden zur Seite.\n\nLasst mich wissen, wenn Ihr bereit seid.", sourceObjective = "Sprecht mit Moira an der Botschaft von Sturmwind, um in die Feuerlande zu reisen und das Fragment des Geschmolzenen Kerns zu verstärken.", completion = "Oberrichter Grimmstein nennt sich jetzt Herold von Ragnaros, wie? Dieser Verräter wird den Tag bereuen, an dem er sich gegen die Dunkeleisenzwerge gestellt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[53353] = { id = 53353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echo von Kriegsfürstin Zaela", description = "Kriegsfürstin Zaela... noch ein Name, der beim Aussprechen einen üblen Geschmack auf der Zunge hinterlässt...\n\nSie hat eine wichtige Rolle dabei gespielt, Garrosh während seines Verfahrens zu befreien, als ihr Drachenmalklan den Tempel des Weißen Tigers angegriffen hat.\n\nEs beschämt mich hinzuzufügen, dass der Drache Kairozdormu ebenfalls beteiligt war. Verlieren wir besser kein Wort mehr darüber.\n\nDer Tempel am Kun-Lai-Gipfel ist unser nächstes Ziel.", sourceObjective = "Bezwingt das Echo von Kriegsfürstin Zaela im Tempel des Weißen Tigers am Kun-Lai-Gipfel.", progress = "Einige der Unseren bringen Schande über unseren Namen.", completion = "Lasst uns von hier fortgehen, bevor ich wütend werde.", sourceObjectiveStatus = "unverified-source-field" }
quests[53354] = { id = 53354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echo von Gul'dan", description = "Um diesen Splitter an den Ort zu binden, zu dem Ihr wollt, müsst Ihr seiner Geschichte folgen.\n\nDer erste Ort, den wir aufsuchen werden, ist das Dunkle Portal in den Verwüsteten Landen.\n\nDort benutzte Gul'dan ein Stück der Vision der Zeit, um zwischen den Realitäten hin- und herzureisen.\n\nSchließt Euch mir dort an, wenn Ihr bereit seid.", sourceObjective = "Bezwingt das Echo von Gul'dan am Dunklen Portal in den Verwüsteten Landen.", progress = "Die Vision der Zeit birgt immer noch Kraft in sich, sie muss nur freigesetzt werden.", completion = "Gul'dan war eine Pestbeule auf allen Ländern, in die er einen Fuß gesetzt hat. Sein Tod war wohlverdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[53355] = { id = 53355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echo von Garrosh Höllschrei", description = "Unser letztes Ziel liegt in den Tiefen unterhalb Eurer Stadt Orgrimmar.\n\nDer Weg dorthin ist versperrt, doch ich kann uns hineinbringen.\n\nTrefft mich vor dem Tor von Orgrimmar und wir werden gemeinsam hinabsteigen.", sourceObjective = "Trefft Euch mit Anachronos vor dem Tor von Orgrimmar und besiegt dann das Echo von Garrosh in der Schlacht um Orgrimmar.", completion = "Ja, er vibriert vor Macht! Das ist genau das, was wir brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53358] = { id = 53358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test of Hyphen Tech" }
quests[53359] = { id = 53359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Stahlhauttrank", progress = "'n paar der best'n Tränke sorg'n dafür, dass Eure Verbündeten 'ne echte Chance ham. Wenn Ihr welche findet, kommt un' sprecht mich an.", completion = "Macht Euch keine Sorg'n. Ich werd mit diesen Tränk'n vorsichtig umgeh'n." }
quests[53360] = { id = 53360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Stahlhauttrank", sourceObjective = "Bringt 2 Stahlhauttränke zu Klara Strand im Hafen von Boralus.", progress = "Stahlhauttränke gewähren einen großartigen Schutz.\n\nWenn Ihr auf Euren Reisen welche auftreibt, nehme ich sie Euch nur zu gerne ab.", completion = "Wunderbar! Genau danach habe ich gesucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[53361] = { id = 53361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Fleischige Keule", description = "Gutes, herzhaftes Fleisch ist genau die Nahrung, die unsere Verbündeten verdienen, bevor sie in die Schlacht ziehen. Außerdem lässt sich damit ein zünftiger Eintopf zubereiten, genau wie ihn unsere Truppen lieben, wenn die Winde gut stehen und die Nächte kälter werden.\n\nWenn Ihr mir ein paar frische gewürzte Lenden besorgt, bringe ich sie gerne zu unseren Versorgungsoffizieren.", sourceObjective = "Sammelt 2 gewürzte Lenden für Senedras im Hafen von Boralus.", progress = "Frisches Fleisch ist einfach das Beste. Wenn wir den Kampf überstehen wollen, müssen wir vorbereitet sein.", completion = "Das wird für einige Zeit reichen.\n\nHabt Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[53362] = { id = 53362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Fleischige Keule", progress = "Leckere Essensrationen geben uns die nötige Kraft für den anstehenden Kampf.", completion = "Eure Spende wird sehr geschätzt." }
quests[53363] = { id = 53363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Trommeln des Mahlstroms", sourceObjective = "Spendet 2 Trommeln des Mahlstroms an Charlane im Hafen von Boralus.", progress = "In der Schlacht sind die diejenigen siegreich, die im Takt einer Trommel marschieren.\n\nWas würdet Ihr dazu sagen, wenn wir unsere Verbündeten ebenfalls in den Genuss kommen lassen?", completion = "Kunstvoll bearbeitete, gute Tierhaut... Sind das Knochen? Das wird wunderbar funktionieren.\n\nIch werde dafür sorgen, dass sie einem guten Zweck zugutekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53364] = { id = 53364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Trommeln des Mahlstroms", progress = "Soldaten verlassen sich in der Schlacht aufeinander. Was sagt Ihr, sollen wir ihnen einen kleinen Moralschub auf dem Schlachtfeld verpassen?", completion = "Diese Trommeln wurden wahrlich von einem Meister seiner Zunft hergestellt.\n\nIch werde sie auf jeden Fall weitergeben. Danke, {name}." }
quests[53365] = { id = 53365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Schlachtflagge: Ansporn", progress = "Unsere Verbündeten versammeln sich unter unseren Bannern auf dem Schlachtfeld. Helft uns, ihnen die Geschwindigkeit und Präzision zu verschaffen, die sie brauchen, um die Frontlinie zu durchbrechen.", completion = "Was für eine schöne Arbeit." }
quests[53366] = { id = 53366, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Schlachtflagge: Ansporn", sourceObjective = "Sammelt 2 Schlachtflaggen: Phalanxverteidigung für Faella im Hafen von Boralus.", progress = "Die schönsten Standarten werden aus feinsten Stoffen und mit bester Handwerkskunst hergestellt.\n\nHabt Ihr vielleicht welche im Angebot?", completion = "Wirklich einzigartig.\n\nUnsere Verbündeten werden sich auf dem Schlachtfeld unter unserem Banner versammeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[53367] = { id = 53367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Organische Diskombobulierungsgranate", progress = "Der größte Vorteil in einer Schlacht ist es, wenn man seinen Feind schon von Weitem erspähen kann. Habt Ihr etwas, das uns dabei helfen könnte?", completion = "Exzellente Arbeit, {name}. Und noch leichter, als ich dachte. Wunderbar." }
quests[53368] = { id = 53368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für das Arathihochland: Organische Diskombobulierungsgranate", progress = "Reichweite, Genauigkeit, qualitativ hochwertiges Metall und allerfeinste Verarbeitung. Das ist das, was wir brauchen.\n\nIHabt Ihr vielleicht ein paar ergattern können?", completion = "Spektakulär! Das ist genau das, wonach ich gesucht habe." }
quests[53369] = { id = 53369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Na'logo muss wandern", description = "Hallo, {name}! Jeder Tortollaner hört in seiner Kindheit Geschichten über Na'logo, einen Tortollaner, der viele Abenteuer erlebt hat. Diese Geschichten fordern den Verstand der jungen Tortollaner, die ausknobeln möchten, wie wohl Na'logo seinen Weg durch die verschiedenen Abenteuer gefunden hat.\n\nMöchtet Ihr es mal probieren?", sourceObjective = "Lernt, wie man Na'logo führt.", completion = "Gut gemacht, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[53370] = { id = 53370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle for Azeroth: Stunde der Abrechnung", description = "Champions der Allianz,\n\nendlich ist die Zeit reif, das zurückzuerobern, was uns rechtmäßig zusteht! Unser finaler Angriff auf Burg Lordaeron beginnt bei Tagesanbruch.\n\nDie Horde und ihr Kriegshäuptling müssen für ihre Verbrechen bezahlen!", sourceObjective = "Trefft Euch mit Meister Mathias Shaw im Hafen von Sturmwind.", completion = "Die Horde wird für all ihre Untaten bezahlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53371] = { id = 53371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flotte Biene", description = "Wir müssen nur etwas Schleim von den Kreaturen aus lebendem Honig einsammeln, die immer noch auf dem Hof unterwegs sind.\n\nWenn Ihr ein paar Phiolen davon mitbringen würdet, können wir die Zutaten zusammenmischen und Hummelbummel geben.\n\nWir sollten ihn nur einmal am Tag füttern, sonst wird er wie einige der anderen Bienen krank.\n\nWir werden dafür sorgen, dass er in null Komma nichts wieder ganz gesund ist!", sourceObjective = "Sammelt 8 Phiolen mit Honigschleim und vermischt sie mit Raimunds Geheimzutat, um die Zuchtformel von Mildenhall herzustellen, und verfüttert sie dann an Hummelbummel.", progress = "Habt Ihr genug Schleim gesammelt?", completion = "Er sieht so viel besser aus!", sourceObjectiveStatus = "unverified-source-field" }
quests[53372] = { id = 53372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle for Azeroth: Stunde der Abrechnung", description = "Champions der Horde, die Zeit ist gekommen.\n\nDie Allianz will Unterstadt unterwerfen und belagert Burg Lordaeron. Ihr sollt Euch umgehend bei Hochfürst Saurfang melden.\n\nBeeilt Euch! Brill ist bereits gefallen und wir haben keine Zeit zu verlieren.", sourceObjective = "Sprecht mit Hochfürst Saurfang in der Feste Grommash.", completion = "Die Allianz marschiert auf Unterstadt zu und will das Niederbrennen von Teldrassil rächen.\n\nWir werden es ihnen nicht gestatten, zu nehmen, was rechtmäßig uns gehört, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[53374] = { id = 53374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "BFA 111-119 E" }
