quests[53404] = { id = 53404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "BFA 120 E" }
quests[53405] = { id = 53405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befreite Macht des Herzens", description = "Ich kann fühlen, wie das Herz von Azeroth stärker wird, {name}. Möglicherweise können wir dem Amulett noch mehr Macht entlocken.\n\nJe stärker es ist, desto besser für Euch. Als wenn es nicht schon genug Mächte gäbe, die sich um das Azerit zanken. Seit kurzem scheinen auch die Diener der Alten Götter danach zu suchen!\n\nKommt. Wir werden die Macht des Azerits, das Ihr gesammelt habt, dazu verwenden, das Herz von Azeroth zu stärken.", sourceObjective = "Sprecht mit Magni Bronzebart und stärkt das Herz von Azeroth.", progress = "Haltet still, während ich das Herz von Azeroth stärke.", completion = "Wir sind auf dem richtigen Weg, Champion. Absorbiert weiter Azerit und verhindert, dass andere es für ihre Zwecke missbrauchen.\n\nAzeroth scheint verwirrt zu sein... besorgt. Ich weiß nicht, was das bedeuten soll, aber ich befürchte, dass alles noch schlimmer wird, bevor es wieder bergauf geht.", sourceObjectiveStatus = "unverified-source-field" }
quests[53406] = { id = 53406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herzkammer", description = "Das Amulett, das Ihr tragt, wird immer stärker, {name}. Aber wenn Ihr mehr von seinem Potenzial freisetzen wollt, müssen wir dorthin gehen, wo wir Azeroths Weltenseele näher sind.\n\nDie Herzkammer!\n\nIch weiß, als Ihr sie das letzte Mal gesehen habt, sah alles nicht so gut aus, aber Ihr solltet mich dort treffen. Ihr werdet sehen, dass wir bei der Heilung der Wunden unserer Welt Fortschritte machen!", sourceObjective = "Verstärkt das Herz von Azeroth in der Herzkammer.", progress = "Die Herzkammer ist der Schlüssel zur Macht des Amuletts.", completion = "Ihr habt die Dunkelheit zurückgedrängt, {name}. Aber sie wird wiederkommen. \n\nJe stärker das Herz von Azeroth wird, desto größer wird auch die Zielscheibe, die Ihr abgebt.\n\nAlso bleibt auf der Hut, Champion. Wir dürfen das Herz nicht verlieren... und Euch auch nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[53414] = { id = 53414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsfront: Die Schlacht um Stromgarde", description = "Wenn die Horde denkt, sie kann Burg Stromgarde stürmen, täuscht sie sich gewaltig. Arathi wird nicht fallen! Das lassen wir nicht zu!\n\nMacht Euch bereit für die Schlacht.", sourceObjective = "Besiegt die Horde in der Schlacht um Stromgarde.", completion = "Gut gekämpft, {name}, obwohl ich glaube, dass es töricht wäre, jetzt schon unsere Deckung fallen zu lassen. Unser Feind wird nicht einfach untätig dasitzen, während wir Burg Stromgarde wieder aufbauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53416] = { id = 53416, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsfront: Die Schlacht um Stromgarde", description = "Unser Feind lässt nichts unversucht, um Arathi für sich zu beanspruchen. Wir können nicht erlauben, dass es in seine Hände fällt! Wir müssen ihn aufhalten, bevor die Burg wieder steht!\n\nZu den Waffen! Die Allianz naht.", sourceObjective = "Besiegt die Allianz in der Schlacht um Stromgarde.", progress = "Wir werden Arathi erobern!", completion = "Ein sehr guter Kampf, {name}. Ein weiteres Mal habt Ihr Euch als furchtloser Krieger der Horde bewiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53430] = { id = 53430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armbrust des Glutordens", sourceObjective = "<Ihr platziert die alte Armbrust an einem ehrenvollen Ort.>", sourceObjectiveStatus = "unverified-source-field" }
quests[53431] = { id = 53431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fläschchen des Glutordens", sourceObjective = "<Ihr platziert das alte Fläschchen an einem ehrenvollen Ort.>", sourceObjectiveStatus = "unverified-source-field" }
quests[53432] = { id = 53432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Messer des Glutordens", sourceObjective = "<Ihr platziert das alte Messer an einem ehrenvollen Ort.>", sourceObjectiveStatus = "unverified-source-field" }
quests[53433] = { id = 53433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hut des Glutordens", sourceObjective = "<Ihr platziert den alten Hut an einem ehrenvollen Ort.>", sourceObjectiveStatus = "unverified-source-field" }
quests[53434] = { id = 53434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verschwundene Fürst", description = "He, Ihr da! Was führt Euch nach Drustvar?\n\nSucht Ihr jemanden aus dem Haus Kronsteig? Da habt Ihr schlechte Karten. Nicht mal wir Gardisten haben in letzter Zeit auch nur ein Sterbenswörtchen von denen gehört. Ich bin mir sicher, dass es gar keine Kronsteigwache mehr geben würde, wenn nicht Marschall Lesner das Kommando über die Wache übernommen hätte.\n\nAm besten Ihr geht gleich wieder Eurer Wege, aber wenn Ihr unbedingt hierbleiben wollt, würde ich rüber nach Fallhafen gehen. Der Bürgermeister dort ist wahrscheinlich die letzte Person hier, die Fremde noch willkommen heißt.\n\nPasst auf Euch auf, <Festländer/Festländerin>. Dunkle Machenschaften sind im Gange.", sourceObjective = "Trefft Cyril Weiß in Fallhafen in Drustvar.", completion = "<Das Bildnis ist durch mächtige Magie geschützt.\n\nMit roher Gewalt kann der Fluch wohl nicht gebrochen werden.>", sourceObjectiveStatus = "unverified-source-field" }
quests[53435] = { id = 53435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azerit für die Horde", description = "Unterstützt die Horde, indem Ihr auf Inselexpeditionen Azerit sammelt.", sourceObjective = "Sammelt Azerit auf Inselexpeditionen.", progress = "Kehrt zu mir zurück, wenn Ihr Eure Unterstützung der Horde abgeschloss'n habt, {name}.", completion = "Für die Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[53436] = { id = 53436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azerit für die Allianz", description = "Unterstützt die Allianz, indem Ihr auf Inselexpeditionen Azerit sammelt.", sourceObjective = "Sammelt Azerit auf Inselexpeditionen.", progress = "Kehrt zu mir zurück, wenn Ihr Eure Unterstützung der Allianz abgeschlossen habt, {name}.", completion = "Für die Allianz!", sourceObjectiveStatus = "unverified-source-field" }
quests[53437] = { id = 53437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "DAS RIESENFLÖZ!!: Rohe Gewalt", description = "Niemand, und ich meine wirklich NIEMAND, betrügt mich und kommt damit davon!\n\nDie Venture Company hat uns bei der Vereinbarung über die Veredelungstechniken für Azerit hintergangen und jetzt ist die Zeit gekommen, da wir es ihnen heimzahlen.\n\nEgal wie Ihr das seht, diesem hinterlistigen Emporkömmling namens Mogul Ratztunk muss ein Ende bereitet werden.\n\nIhr kümmert Euch um ihn, während ich uns das zurückhole, was er uns schuldet.\n\nWir sollten wohl Pestrufer davon berichten, oder? Wenn er uns dann erklärt, was wir tun sollen, steht Ihr einfach nur da und nickt freundlich, okay? Wir regeln das auf unsere Art und Weise.", sourceObjective = "Überbringt die endgültige, tödliche Nachricht Mogul Ratztunk im RIESENFLÖZ!!", completion = "Ihr habt mir da wirklich einen riesigen Gefallen getan, {name}. Möge dieser grüne Bastard in einem schäbigen Grab verrotten.", sourceObjectiveStatus = "unverified-source-field" }
quests[53438] = { id = 53438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Wyvernwilderer", description = "Soldaten der Horde!\n\nVor einigen Nächten haben ein paar törichte Menschen einen unserer stärksten Wyvern entführt.\n\nIch biete demjenigen eine hohe Belohnung, der diese Diebe stellt und festnagelt!", sourceObjective = "Tötet Lindel den Langfinger und den stillen Boris.", completion = "Der Wyvern ist fast unversehrt zurückgekommen. Er wird bereit sein, uns in die Schlacht zu fliegen, sobald wir ihn brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53439] = { id = 53439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutgetränkte Fluten", description = "In Zandalar gibt's keine Sirenen, aber unsre Seeleute ham schon von ihnen gehört. Sie nennen sie Bwon'tulak, Todessängerinnen.\n\nMein Schiff is' auf Grund gelauf'n und meine komplette Mannschaft is' den Todessängerinnen zum Opfer gefall'n.\n\nJette hat mir damals das Leben gerettet, also helfe ich jetzt, diese Leute zu beschütz'n.\n\nSirenen sind 'ne Plage der Meere, egal unter welcher Flagge man segelt. Nehmt ihr Blut un' färbt die Wellen rot!", sourceObjective = "Tötet 8 klagende Sirenen.", completion = "Durch Euch is' die See wieder sicherer für alle. Best'n Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[53440] = { id = 53440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Die Hornisse", description = "Jetzt reicht's. Ich setze ein Kopfgeld auf diese verfluchte Hornisse aus.\n\nKann endlich mal jemand dieses Insekt ausschalten?!", sourceObjective = "Tötet die Hornisse.", completion = "Die Hornisse ist tot! Gute Arbeit.\n\nIch will nicht von einem Insekt umgebracht werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[53442] = { id = 53442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schiffbrüchigen", description = "Ihr seht nicht aus, als wärt Ihr von hier. Habt Ihr ein Glück, dass die Sirenen Euch noch nicht die Haut abgezogen haben.\n\nWenn Ihr Vorräte aufstocken oder Euch am Feuer wärmen wollt, begebt Euch einfach zum Lager auf dem Hügel hinter mir.\n\nAlle dort wurden hier angespült. Inzwischen müssen sich Besatzungen von vier oder fünf Schiffswracks angesammelt haben. Sie halten zusammen und versuchen zu überleben.\n\nSprecht mit Jette der Klinge. Denkt nicht zu viel über ihren Namen nach, sie ist eigentlich ganz lieb.", sourceObjective = "Sprecht mit Jette der Klinge an der Schiffbruchhöhe.", completion = "Seid Ihr auch schiffbrüchig? Oder sucht Ihr nur Arbeit?", sourceObjectiveStatus = "unverified-source-field" }
quests[53443] = { id = 53443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meine liebsten Dinge", description = "Die Welt da draußen ist hart.\n\nEs gibt Piraten, tödliche Monster.\n\nKohldampfsören hat endlosen Ärger mit seiner Verdauung.\n\nNichts hilft einem besser, Ruhe zu bewahren, als ein altes Andenken. Etwas, das einen an seine Heimat denken lässt. Etwas, für das man immer weitermacht.\n\nHört Euch ein wenig im Lager um. Findet heraus, was die Leute dort draußen im Priel verloren haben. Wenn Ihr davon etwas zurückbringen könntet, wäre das eine großzügige Geste.\n\nIch? Oh... Ich habe ein Medaillon verloren...\n\nIst egal. Das ist zu klein, das würdet Ihr nie finden. Ist nichts Besonderes. Macht Euch keine Gedanken darüber.", sourceObjective = "Fragt den leutseligen Piet, Kohldampfsören und Friemelkalle über ihre verlorenen Andenken aus und findet sie danach im Klagenden Priel.", progress = "Wir alle haben etwas in den Fluten verloren.\n\nManche mehr als andere.", completion = "Ich hätte nie geglaubt, dass Ihr wirklich all diese Sachen finden würdet!\n\nWir haben nicht viel, aber nehmt wenigstens dies für Eure Bemühungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53444] = { id = 53444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glänzendes Medaillon", description = "<Zwischen dem mit den Wellen auf und ab tanzenden Treibgut fällt Euch ein metallenes Glänzen ins Auge. Ihr wühlt im dichten Seetang und entdeckt ein einfaches, aber stabiles Medaillon.\n\nAls Ihr es öffnet, entdeckt Ihr die Zeichnung einer Frau mit feuerroten Haaren.\n\nIhr Arm ruht auf der Schulter einer Frau mit kurzem rotbraunem Haar und die beiden lächeln den Künstler warmherzig an.>", sourceObjective = "Bringt das glänzende Medaillon Jette der Klinge zurück.", progress = "Hm? Was habt Ihr denn da?", completion = "Ist das etwa?\n\n<Jette nimmt das Medaillon und öffnet es vorsichtig. Tränen sammeln sich in ihren Augen, als sie es wieder schließt und in ihrer Jacke verstaut.>\n\nIch danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[53445] = { id = 53445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstummen der Schwestern", description = "Die Sirenen des Priels haben schon endlose Schiffe in ihr Verderben gelockt. Es wäre ein Segen für alle Seefahrer, wenn jemand sie beseitigen würde.\n\nAber Ihr könnt sie nicht einfach alle töten. Nur ein Narr würde so etwas probieren.\n\nDie echte Gefahr sind die Ältesten. Man nennt sie die \"Schwestern\". Sie sind größer, klüger und stärker als die Jüngeren. Ihre Stimmen dringen bis aufs Meer hinaus und locken die großen \"Fänge\" an.\n\nIch konnte zwei von ihnen bis zu einem Versteck am nördlichen Ende des Priels verfolgen, kann sie aber nicht allein stellen.", sourceObjective = "Tötet Patheope und Nolpe.", completion = "Indem Ihr ihr tödliches Lied verstummen lassen habt, habt Ihr zahllose Leben gerettet.", sourceObjectiveStatus = "unverified-source-field" }
quests[53446] = { id = 53446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lokale Spezialitäten", description = "Ich bin am VERHUNGERN.\n\nNicht so am Verhungern, wie als wir hier angekommen sind, aber Ihr wisst schon... emotional am Verhungern.\n\nIn letzter Zeit hatte ich bei Austern nicht viel Glück und Seetangsuppe schlägt mir auf den Magen. Wenn ich noch mehr von dem Zeug essen muss, werden die anderen Schiffbrüchigen mich vermutlich den Haien zum Fraß vorwerfen.\n\nWie die Gezeitenlauerer wohl schmecken? Die sehen schön saftig aus. Könnte man sicher schmackhaft dämpfen.\n\nWürdet Ihr mir ein paar bringen? Ich bin kein großer Jäger. Aber ich würde sie mit Euch teilen!", sourceObjective = "Sammelt 5 saftige Lauererschwänze.", progress = "<Sörens Magen knurrt laut.>", completion = "Oh, Ihr habt mir das Leben gerettet!\n\nWartet nur einen Augenblick, die habe ich im Nu gekocht!", sourceObjectiveStatus = "unverified-source-field" }
quests[53449] = { id = 53449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildgewordene Affenbande", description = "Allianz, musste das sein? Habt Ihr Lust auf Schererei'n?\n\nDie Zandalari sind geschockt, von neuen Gorillas mit Schmock.\n\nDiese Gorillas sind frech, und haben auch 'nen Sprech'.\n\nGorillas sind am Rappeln, denn ihr König ist ein Nappel.\n\nFühren ist zwar wichtig, aber dieser Knatzel blickt's nicht.\n\nIch schick Flapp-Flapp voraus. Macht dem Knatzkönig den Garaus.", sourceObjective = "Reist zum Gorillagraben.", completion = "UUK! Gerade zur rechten Zeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[53450] = { id = 53450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "König Da'ka", description = "König Da'ka? Eher König Ka'ka.\n\nMein König will, dass ich mit diesem neuen König rede. Aber dieser neue König hat mir meine Dingens gestohlen und hat versucht, mir meine Flügel zu klauen.\n\nVerfiddelte Verhandlungen. Geht und zeigt es diesem wilden Nappel.", sourceObjective = "Tötet König Da'ka.", completion = "Gut. Gorillas müssen lern', dass Könige mehr'n. Und wenn sie nicht mehr'n, dann sie nicht lern'.", sourceObjectiveStatus = "unverified-source-field" }
quests[53451] = { id = 53451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Tobender Erdwächter", description = "Ich habe eine Reihe formaler Beschwerden über einen Erdelementar erhalten, der sich mitten auf unserem Späherpfad niedergelassen hat.\n\nNormalerweise würde ich das einfach ignorieren, aber je schneller wir hier fertig sind, desto besser. Niemand will länger in diesen frostigen Hügeln bleiben als unbedingt nötig.\n\nIch biete demjenigen, der das Monster erledigt, ein hohes Kopfgeld!", sourceObjective = "Tötet den tobenden Erdwächter westlich des Anwesens der Norwinsens.", completion = "Jetzt sollten die Beschwerden aufhören. Danke vielmals!", sourceObjectiveStatus = "unverified-source-field" }
quests[53452] = { id = 53452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorillakriegsführung", description = "Ihr kommt genau zur rechten Zeit. Ich danke Euch für Eure Hilfe.\n\nIm Gorillagraben herrscht kein Frieden mehr. Durch das Kaja'mit sind wir zwar höchst intelligent und beredt geworden, doch damit kam auch der Krieg zu uns.\n\nMeine Brüder gedenken nicht, zu kämpfen. Unsere Passivität hat uns jedoch zu Opfern gemacht.\n\nIch bitte Euch, befreit meine Kameraden. Sie sind in der ganzen Schlucht verteilt, eingesperrt in Käfigen und unter Bewachung. Eilt Euch!", sourceObjective = "Rettet 6 friedliebende Gorillas.", completion = "Ich danke Euch, mein Freund. Mit wahrem Heldenmut habt Ihr meinen Brüdern die Freiheit zurückgegeben. Wir sehen uns in Bälde wieder.", sourceObjectiveStatus = "unverified-source-field" }
quests[53453] = { id = 53453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorillas im Schmock", description = "Wie mein Großfiddel immer gesagt hat: Wenn ein Nappel Schmock aus dem Knatzloch bläst, musst du ihm das Knatzloch stopfen.\n\nDiese Da'kaninappel schnüffeln grünen Rauch aus ihren Knatzlöchern im Boden. Der Schmock macht sie schlau und gemein. Schlau ist nicht schlimm, gemein aber schon.\n\nGeht in den Gorillagraben und stopft diese Knatzlöcher ein für alle Mal!", sourceObjective = "Verschließt die Kaja'mitdampfventile im Gorillagraben.", completion = "Haha. Gut. Können ja nicht zulassen, dass die Gorillas ausnappeln und keiner mehr vor ihnen sicher ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[53454] = { id = 53454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Rüstmeister Ssylis", description = "Ein paar Piraten haben sich mit einer Vorratskiste davongemacht, die weiter weg von hier gelandet ist, als vorgesehen war.\n\nIch glaube nicht, dass sich darin etwas Wertvolles befand, aber jetzt wissen die Piraten, dass wir hier sind.\n\nDer Anführer war einer dieser großen Echsenmänner. Der Arbeiter, der ihn tötet, bekommt den doppelten Wochenlohn!", sourceObjective = "Tötet Rüstmeister Ssylis in der Krakenfluchbucht.", completion = "Gute Arbeit! Das bedeutet hoffentlich, dass wir jetzt weniger Vorratsabwürfe verlieren werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[53455] = { id = 53455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Die blutigen Halsabschneider", description = "Wegen zahlreicher und niederträchtiger Vergehen gegen die Lordadmiralin: Schmuggel, Fälschung, Seefahrt unter falscher Flagge, Plünderei, Wilderei, Raub, Brandschatzung, mutwillige Beschädigung, Amtsanmaßung durch Ausgabe als Offiziere der Marine von Kul Tiras, Brandstiftung, Entführung, Folter, Piraterie, Meineid, Diebstahl und Ansichnahme mehrerer Metlieferungen.\n\nAuf die Köpfe der blutigen Halsabschneider ist eine Belohnung ausgesetzt, die bei einem Beweis ihres Ablebens in Gänze ausgezahlt wird.", sourceObjective = "Tötet die blutigen Halsabschneider in der Nähe von Falkenforst.", completion = "Ich sage Euch, ich bin nicht traurig drum, dass die weg sind.\n\nIch weiß, Ihr steht mit den Kul Tiranern nicht gerade auf gutem Fuße, also wie wäre es, wenn ich Euch die Belohnung vorschieße und dann meine Verbindungen nutze, um sie zu bekommen. Wie klingt das?", sourceObjectiveStatus = "unverified-source-field" }
quests[53456] = { id = 53456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Die Frostjägerin", description = "Achtung, an alle Interessierten! Hier lässt sich Geld scheffeln!!!!\n\nAuf dem Pass ist eine große Wölfin, die Leute jagt. Sie hat Geschmack an Goblins gefunden. Keiner hat Zeit, von einem Wolf gefressen werden, also bringt die Frostjägerin zur Strecke und ich bezahle Euch für Eure Mühen.\n\n- Susi Bolzschraub", sourceObjective = "Besiegt die Frostjägerin in der Nähe des Hochwegpasses.", completion = "Hey, habt Ihr die große Wölfin erledigt? Klasse!\n\nEs ist gut, zu wissen, dass sie keine unserer Minenarbeiter mehr verspeisen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[53457] = { id = 53457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfgeld des Rüstmeisters", progress = "Um den Feind zu besiegen, braucht Ihr Ausrüstung im Topzustand. Wenn Ihr Euch keine mächtigere Ausrüstung beschaffen konntet, kann ich für Euch welche vom Rüstmeister anfordern.", completion = "Sieg um jeden Preis." }
quests[53458] = { id = 53458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Wassergram", description = "Eine grässliche Monstrosität aus Fleisch und Holz terrorisiert die Gegend um den Fluss in der Nähe. Wenn man mehr darüber wüsste, wie die Kreatur kämpft, könnte es interessante Daten geben!\n\nBitte meldet alles, was Ihr herausfinden könnt, Susi Bolzschraub in Krazzelfrazz.", sourceObjective = "Besiegt Wassergram außerhalb von Fallhafen.", completion = "Hallo! Ihr habt ein paar großartige Daten von diesem Monster bekommen.\n\nHier ist eine kleine Belohnung dafür, dass Ihr so ein großartiger Forschungsassistent wart.", sourceObjectiveStatus = "unverified-source-field" }
quests[53459] = { id = 53459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Schwester Lilias", description = "Die Friedensbewahrer von Krazzelfrazz suchen einen fähigen Soldaten, der eine Bedrohung im nahe gelegenen Korlach beseitigen kann.\n\nEine Hexe namens Schwester Lilias wird gesucht, weil sie viele unserer Leute gefoltert und getötet hat. Ihr Ableben wäre ein großer Segen für die Horde.\n\nWeist ihren Kopf vor, um Eure verdiente Belohnung zu erhalten.", sourceObjective = "Besorgt Schwester Lilias' Kopf von Schwester Lilias in Korlach.", progress = "Hey, wir haben ein Hexenproblem. Könnt Ihr Euch darum kümmern?", completion = "Ihr habt die Hexe erledigt? Großartig! Sie hat unserer Operation hier wirklich Steine in den Weg gelegt.\n\nHier ist das Kopfgeld. Es wird komplett ausgezahlt. War ein Vergnügen, mit Euch Geschäfte zu machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53461] = { id = 53461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silberner Hoffnungsschimmer", description = "He, Ihr da! Ich habe Euch ein Geschäft vorzuschlagen. Die Einheimischen hier scheinen einen Silbertick zu haben und wir haben mit einer Mine westlich von hier den Hauptgewinn gezogen.\n\nLeider gibt es dort ein kleines Spinnenproblem...\n\nDie Minenarbeiter, die wir dort hinuntergeschickt haben, gibt es wahrscheinlich schon gar nicht mehr, aber da unten ist immer noch Silber. Wenn Ihr dorthingehen und mir etwas davon holen könnt, setzen wir den Preis hoch und machen ein Vermögen!\n\nWas meint Ihr?", sourceObjective = "Sammelt 10 Silberklumpen in der Rauhügelmine.", progress = "Habt Ihr das Silber gefunden?", completion = "So macht man das!\n\nOh, ein paar der Minenarbeiter waren noch am Leben? Jetzt redet Ihr wirres Zeug.", sourceObjectiveStatus = "unverified-source-field" }
quests[53462] = { id = 53462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ordentlich eingewickelt", description = "Ich bin nicht die Einzige, die in dieser Mine festsitzt. Riegelflöz hat auch alle anderen Minenarbeiter den Spinnen überlassen.\n\nDa draußen sind vielleicht noch ein paar am Leben. Könnt Ihr helfen? Ich würde es wirklich zu schätzen wissen, wenn nicht alle meine Freunde sterben würden.", sourceObjective = "Zerstört zuckende Kokons, um 8 Minenarbeiter in der Rauhügelmine zu retten.", completion = "Puh! Ich bin froh, dass ein paar von uns es hier herausgeschafft haben.\n\nIch in ziemlich sicher, dass ich nach all dem hier eine Arachnophobie entwickelt habe...", sourceObjectiveStatus = "unverified-source-field" }
quests[53463] = { id = 53463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Widerlinge mit acht Beinen", description = "Dieser Mistkerl Riegelflöz hat uns hier in die Mine geschickt, um dann, als die Spinnen auftauchten, seine Siebensachen zu packen und uns hier sitzen zu lassen! Jetzt sitze ich hier fest und sehe nur noch eine Million Beine und Augen in jeder Richtung.\n\nIhr seht aus, als ob Ihr ein zäher Brocken seid. Könnt Ihr mir einen Weg freikämpfen? Es soll Euer Schaden nicht sein.", sourceObjective = "Tötet 20 Gallenzahnspinnen in der Rauhügelmine.", completion = "Welch eine Erleichterung!\n\nJetzt kann ich nach Krazzelfrazz zurückgehen und Riegelflöz mal gewaltig die Meinung geigen!", sourceObjectiveStatus = "unverified-source-field" }
quests[53464] = { id = 53464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Dorf Schluchtbach", description = "<Dieses Buch ist ein Verzeichnis aller Einwohner von Schluchtbach.\n\nBis auf ein paar wenige Namen sind alle durchgestrichen.>", sourceObjective = "Findet heraus, welches Schicksal die Bewohner von Schluchtbach ereilt hat.", completion = "<Der Leichnam ist fast bis zur Unkenntlichkeit entstellt und zerfetzt.\n\nIhr könnt nur annehmen, dass dies die \"Annie\" ist, die in dem Verzeichnis erwähnt wird.>", sourceObjectiveStatus = "unverified-source-field" }
quests[53465] = { id = 53465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teekränzchen", description = "<Ihr hört Schritte hinter Euch.>", sourceObjective = "Findet Anneke Lehmann.", sourceObjectiveStatus = "unverified-source-field" }
quests[53466] = { id = 53466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vision der Zeit", description = "Wollt Ihr hören, wie die Orcs der Mag'har der Horde beigetreten sind? Wir haben wohl nie einen Verbündeten auf bizarrere Weise gewonnen!\n\nAlles begann mit einem Plan von Etrigg. Er hatte ein Fragment der Vision der Zeit, die Garrosh Höllschrei benutzt hatte, um nach Draenor zu reisen.\n\nGroßtelemant Oculeth glaubte, es gäbe einen Weg, nach Draenor zurückzureisen und die Mag'har dazu zu bringen, der Horde beizutreten.\n\nDie Geschichte beginnt mit einem Besuch bei Oculeth in Zuldazar...", sourceObjective = "Trefft Euch mit Großtelemant Oculeth in Zuldazar.", completion = "{name}, es ist schön, Euch zu sehen. Ich suche schon seit einiger Zeit nach jemandem, der mir hilft, dieses Fragment abzustimmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53467] = { id = 53467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höhlen der Zeit", description = "Wäre das Fragment der Vision der Zeit nicht erschöpft, könnte ich Euch damit schicken, wohin Ihr möchtet. Aber meine Spezialität ist Teleportation, nicht Chronomantie.\n\nZeitmagie war die Spezialität unserer früheren Anführerin, Großmagistrix Elisande. Einen großen Teil ihres Wissens hat sie mit ins Grab genommen.\n\nMan sagt, dass Elisande Beschwörungen beherrschte, die sonst nur die Bronzedrachen kennen. Vielleicht sind sie bereit, Euch zu helfen.", sourceObjective = "Trefft Euch mit Anachronos in den Höhlen der Zeit.", completion = "Ist es schon Zeit für Euren Besuch bei mir? Ja, ich nehme an, das ist es wohl.", sourceObjectiveStatus = "unverified-source-field" }
quests[53476] = { id = 53476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schriftrollen des Großen Meeres", description = "<Staub fällt vom Schriftrollenbehälter, als Ihr ihn an Euch nehmt. Darunter kommt eine verwitterte, aber liebevoll angefertigte Radierung zum Vorschein, die eine tortollanische Pilgerschaft darstellt.\n\nDer Behälter hat Platz für zwölf Schriftrollen, aber nur einer davon ist belegt. Ein komplettes Set wäre einem tortollanischen Sammler sicherlich einiges wert.>", sourceObjective = "Sammelt ein Schriftrollenset, das die tortollanische Pilgerschaft darstellt.", completion = "Meine Güte! Ist das ein kompletter Satz der Zermürbenden Pilgerschaft? Und dann noch in einem Schriftrollenbehälter der ersten Generation?\n\nHerrjeh, ich habe so einen seit Jahrzehnten nicht gesehen! Hier, hier, ich habe einen hübschen Hut, den ich vor einigen Jahren von einem hochgewachsenen Mann bei einem Handel erstanden habe. Er sagte, er wäre \"aus dem Norden\".\n\nHabe ich Euch je die Geschichten erzählt, die mir der Vater meines Großvaters mütterlicherseits über die Tage der Pilgerschaft erzählt hat? Alles begann mit diesem Schuft aus... Hey, wo wollt Ihr hin?", sourceObjectiveStatus = "unverified-source-field" }
quests[53478] = { id = 53478, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eroberungsbelohnung", sourceObjective = "Eure Kühnheit auf dem Schlachtfeld ist ohnegleichen.", sourceObjectiveStatus = "unverified-source-field" }
