quests[53498] = { id = 53498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchhaltevermögen" }
quests[53500] = { id = 53500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fremder in einem fremden Land", description = "Willkommen in Sturmwind, {race}. Ich lade Euch ein, unsere prächtige Stadt zu erkunden. Hm, Ihr seht aus wie jemand, der sich an Höhlen und dergleichen erfreut! In Sturmwind gibt es viele dunkle Ecken zu erforschen.\n\nAber das kann warten. Ein Bronzedrache wollte Euch sprechen. Sie sitzt unter dem Baum in der Nähe, ausgerechnet auf einem Stundenglas!\n\nUnd danach erwartet Euch einer Eurer Abgesandten, der Euch in der Stadt willkommen heißen will. Klingt, als hättet Ihr einen langen Tag vor Euch!\n\nIch wünsche einen angenehmen Aufenthalt, {name}!", sourceObjective = "Sprecht mit Chromie in Sturmwind.", progress = "Seid gegrüßt, {name}.", completion = "Willkommen in Sturmwind. Viel zu viel Sonne hier draußen, wenn Ihr mich fragt.\n\nIch bin dann mal weg und suche nach Abenteuern! Und nach einem Ort, wo es etwas dunkler ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[53502] = { id = 53502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fremder in einem fremden Land", description = "Hallo, ich bin Botschafter Schwarzwacht.\n\nEs ist mir eine Ehre, Euch in Orgrimmar willkommen zu heißen, {race}.\n\n<Er lächelt gekünstelt.>\n\nNun, da sich ein Leben voller Abenteuer vor Euch auftut, seid versichert, dass... ähm...\n\nWisst Ihr was? Ich habe diese Begrüßung heute den ganzen Tag immer wieder abgespult. Mir reicht's.\n\nSprecht mit Chromie auf dem Stundenglas. Und dann sprecht mit Eurem Abgesandten. Kusch!", sourceObjective = "Sprecht mit Chromie in Orgrimmar.", progress = "Eine andere Welt... eine andere Zeit... dies ist wahrlich ein Zeitalter voller Wunder.", completion = "Hier kann man wirklich gut abschneiden, wenn Ihr wisst, was ich meine. Ich meine, ich liebe es, wenn ich einen guten Schnitt machen kann.\n\nWie sieht es bei Euch aus? Vielleicht können wir ja eines Tages zusammen den einen oder anderen Schnitt machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53520] = { id = 53520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprengen!" }
quests[53549] = { id = 53549, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfgeldtasche" }
quests[53550] = { id = 53550, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Führungswechsel", description = "Meiner Erfahrung nach mag es niemand, von seinem Hab und Gut vertrieben zu werden.\n\nNormalerweise würde ich die ganze Macht der Horde gegen sie entfesseln, aber wir haben keine Zeit, einen langen Feldzug gegen diese Kreaturen zu führen.\n\nSie werden versuchen, bei ihren Anführern Hoffnung, Inspiration und Anleitung zu finden. Und das vergeblich.\n\nIhr seid das Instrument meines Willens, {name}. Also sorgt dafür, dass sie sich ihm beugen.", sourceObjective = "Bezwingt den Ältesten Brolg, Gren Fetzfell und den Ältesten Braunpfote.", sourceObjectiveStatus = "unverified-source-field" }
quests[53551] = { id = 53551, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elfen in der Maschine", description = "Die Horde hat hier bereits ihr Lager aufgeschlagen. Aber noch sind wir nicht besiegt.\n\nIhre Kriegsmaschinen sind zwar furchterregend, aber es sind nur Maschinen. Und bekanntlich bekommen Maschinen Probleme, wenn man in ihrem Innenleben herumfuhrwerkt.\n\nAlso, wenn wir ein paar von ihnen sabotieren, kann das Dutzende von Leben retten.\n\nDiese Gelegenheit sollten wir nutzen.", sourceObjective = "Sabotiert 5 Verwüster der Horde im Bau der Schwarzfelle.", progress = "Wir müssen diese Verwüster zerstören!", completion = "Wir haben hier getan, was wir konnten. Kommt, wir müssen unsere Mission zu Ende bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53552] = { id = 53552, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wilde Sause" }
