quests[53563] = { id = 53563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "BFA 111-119 E" }
quests[53566] = { id = 53566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkeleisenzwerge", description = "Ich kann Euch nicht genug danken, {name}. Ohne Eure Hilfe hätten wir Eisenfeind verloren und der Schwarze Amboss hätte niemals repariert werden können.\n\nUnd noch mehr als das. Ihr habt allen Dunkeleisenzwergen im Berg gezeigt, was es heißt, Teil von etwas Größerem zu sein, Teil der Allianz zu sein.\n\nEs ist an der Zeit, König Anduin zu sagen, dass mein Volk hinter ihm steht.", sourceObjective = "Sprecht mit Aysa Wolkensänger bei der Botschaft von Sturmwind, um das Ende dieser Geschichte zu hören.", completion = "Ihr habt der Allianz die Treue der Dunkeleisenzwerge gesichert und somit unsere Stärke erneuert.\n\nKönigin-Regentin Thaurissan und ich stehen beide in Eurer Schuld. Habt Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[53583] = { id = 53583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsere Taktik anpassen", description = "Um die besten Chancen in diesem Krieg zu haben, müssen wir uns anpassen und neue Strategien entwickeln. Möglichkeiten uns weiterzuentwickeln warten überall auf uns, aber sie erfordern Hingabe und Beharrlichkeit.\n\nIch habe eine Liste potenzieller Forschungsmöglichkeiten zu Eurer Begutachtung erstellt. Jede davon mag für sich unscheinbar wirken, aber zusammen könnten sie uns den entscheidenden Vorteil geben, den wir brauchen. Gebt mir Bescheid, wenn Ihr Euch für eine Forschung entschieden habt.", sourceObjective = "Sprecht mit Alleria Windläufer, um die Forschung an einer Aufwertung zu beginnen.", progress = "Habt Ihr Euch schon entschieden?", completion = "Ausgezeichnet. Wir kümmern uns sofort darum.", sourceObjectiveStatus = "unverified-source-field" }
quests[53602] = { id = 53602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsere Taktik anpassen", description = "Dieser Krieg kann nicht mit Stärke und Macht allein gewonnen werden. Nehmt während des Kampfes Eure Umgebung in Euch auf und verwandelt sie in einen Vorteil gegen Euren Feind.\n\nIch habe eine Liste von Modifikationen zu Eurer Auswahl. Jede davon mag für sich unscheinbar wirken, aber zusammen könnten sie uns den entscheidenden Vorteil geben, den wir brauchen.\n\nSagt mir Bescheid, was wir für Euch verbessern sollen.", sourceObjective = "Sprecht mit Etrigg, um die Forschung an einer Aufwertung zu beginnen.", progress = "Wie habt Ihr Euch entschieden?", completion = "Ausgezeichnet. Wir kümmern uns sofort darum.", sourceObjectiveStatus = "unverified-source-field" }
quests[53604] = { id = 53604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Truppen ausschalten", description = "Sie haben vor uns eine Armee aufgestellt, {name}. Aber es macht keinen Unterschied – die Kriegsmaschinerie der Horde hält niemand auf.\n\nBetretet die Meistergleve und schaltet ihre Krieger, ihre Schildwachen und jeden anderen aus, der eine Klinge gegen meine Soldaten erheben könnte.\n\nFegt den mickrigen Abschaum weg, der versucht, das Unvermeidliche hinauszuzögern.", sourceObjective = "Tötet Truppen der Nachtelfen in der Meistergleve.", completion = "Damit sind wir meinem Ziel einen Schritt näher.", sourceObjectiveStatus = "unverified-source-field" }
quests[53605] = { id = 53605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein glevierendes Missverständnis", description = "Die Kaldorei haben ihre Belagerungswaffen ins Feld geschickt. Sie setzen sie in diesem Moment gegen meine eigenen ein.\n\nOhne diese Verwüster können wir Teldrassil nicht einnehmen. Geht, zerstört ihre Glevenschleudern und zwar so schnell wie irgend möglich.\n\nWenn sie denken, sie können meinen Vormarsch hier aufhalten, denken sie falsch. Zeigt ihnen das Ausmaß ihres Irrtums, {name}.", sourceObjective = "Zerstört die Glevenschleudern in der Meistergleve.", completion = "Das war ein einfacher Sieg. Aber glaubt nicht, dass es so einfach bleiben wird. Malfurion wird mit seinen Truppen zurückkehren, aber bis dahin werden wir weitermachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53606] = { id = 53606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aggressive Inspiration", description = "Nichts spornt die Horde mehr an als der Moment, in dem ihr Banner stolz in den Ruinen einer feindlichen Festung weht.\n\nGeht zum Bau der Schwarzfelle und nehmt ihn ein. Stellt dann die Hordenbanner auf und lasst niemanden daran zweifeln, wer jetzt über dieses Land herrscht.", sourceObjective = "Platziert 3 Hordenbanner im Bau der Schwarzfelle.", completion = "Jetzt ist nicht die Zeit für subtile Gesten.", sourceObjectiveStatus = "unverified-source-field" }
quests[53608] = { id = 53608, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treibstoff für die Kriegsmaschinerie der Horde", description = "Ihr habt den Kriegshäuptling gehört! In den Ruinen da drüben schießt Azerit aus dem Boden und die Nachtelfen versuchen, es sich unter den Nagel zu reißen.\n\nAlso begebt Euch zu den Ruinen und sammelt etwas von dem Zeug ein. Unsere gesamte Offensive ist in Gefahr, wenn die Nachtelfen das Azerit in ihre Hände bekommen!", sourceObjective = "Sammelt Azerit aus 6 Azeritvorkommen.", completion = "Das sollte genügen! Die Nachtelfen werden gar nicht wissen, wie ihnen geschieht.", sourceObjectiveStatus = "unverified-source-field" }
quests[53609] = { id = 53609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine sehr klare Botschaft", description = "Die Allianz hat das Azerit vor uns erreicht. Hier wimmelt es nur so von Nachtelfen!\n\nTötet alle, die Ihr seht. Wir müssen sichergehen, dass nicht einer von ihnen der Allianz auch nur eine Unze Azerit überbringt!", sourceObjective = "Tötet 10 Streitkräfte der Nachtelfen.", completion = "Puh, das war ganz schön knapp. Diese Nachtelfen hätten besser fliehen sollen, so lange sie noch die Gelegenheit dazu hatten!", sourceObjectiveStatus = "unverified-source-field" }
quests[53610] = { id = 53610, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagt sie hinaus", description = "Jetzt kommt es drauf an, {name}.\n\nNur Lor'danel steht uns noch im Weg, bevor wir Darnassus einnehmen und Kalimdor zurückerobern können.\n\nBesiegt die Verteidiger. Wir können nicht riskieren, auch nur einen einzigen Feind entkommen zu lassen, bis wir die Kontrolle über den Weltenbaum erlangt haben.\n\nIch will, dass hier wieder Ordnung herrscht, wenn der Kriegshäuptling eintrifft.", sourceObjective = "Tötet 15 Verteidiger von Lor'danel.", completion = "Das war fast schon zu einfach.", sourceObjectiveStatus = "unverified-source-field" }
quests[53616] = { id = 53616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Messer der Verlassenen", description = "Seid vorsichtig. Nicht alles ist so, wie es scheint. Die Schlächter, die hierfür verantwortlich sind, verbergen sich noch immer in Astranaar.\n\nWenn Ihr sie aufspürt, {name}, dann gebt ihnen, was sie verdienen.", sourceObjective = "Tötet 8 Auftragsmörder der Verlassenen in Astranaar.", completion = "Diese dreckigen Kreaturen verdienen nichts anderes.", sourceObjectiveStatus = "unverified-source-field" }
quests[53617] = { id = 53617, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnade für die Wahnsinnigen", description = "Die Zerstörung, die die Horde angerichtet hat, treibt die Kinder des Waldes in den Wahnsinn.\n\nDie Furbolgs der Schwarzfelle leiden ganz besonders. Sie sind dem Wahn verfallen und stellen für alle eine Bedrohung dar. Wenn wir nichts unternehmen, könnten sie uns in den Rücken fallen, während wir gegen die Horde kämpfen.\n\nSo sehr es mich auch schmerzt, ich bitte Euch, diese Geschöpfe im Zwielichttal von ihrem Leid zu erlösen, bevor sie noch andere in Gefahr bringen.", sourceObjective = "Tötet 10 rasende Furbolgs der Schwarzfelle.", completion = "Es ist eine Tragödie, dass so viele Furbolgs sterben mussten, aber es war nicht zu vermeiden. In ihrem Wahnsinn waren sie für unsere eigenen Leute eine Gefahr und wir hätten an zwei Fronten kämpfen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53619] = { id = 53619, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azeritentzug", description = "Diese Substanz, Azerit, verursacht Onu Schmerzen... und die Horde scheint sehr erpicht darauf, es einzusammeln.\n\nWir dürfen das nicht zulassen. Sammelt so viel Azerit, wie Ihr finden könnt. Und stellt sicher, dass die Horde es nicht in die Finger bekommt.", sourceObjective = "Sammelt Azerit aus 6 Azeritvorkommen.", completion = "Ausgezeichnete Arbeit... dieses Azerit ist wirklich eine mächtige Substanz. Wir dürfen nicht zulassen, dass die Horde Zugriff darauf bekommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[53621] = { id = 53621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Horde zugelassen", description = "Die Streitkräfte der Horde in diesem Gebiet versuchen, so viel Azerit wie möglich zu sammeln. Ohne Zweifel wollen sie es als Waffe einsetzen.\n \nTötet alle Streitkräfte der Horde, auf die Ihr trefft. Ihr dürft nicht zulassen, dass sie dieses Azerit in die Hände bekommen!", sourceObjective = "Tötet 10 Kämpfer der Horde in Nazj'vel.", completion = "Wir werden der Invasion der Horde hier und jetzt ein Ende setzen. Ohne dieses Azerit können sie nicht gewinnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53622] = { id = 53622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung von Lor'danel", description = "Die Horde greift von Norden aus an! Ihr müsst Lor'danel beschützen, {name}.\n\nHelft unseren Streitkräften dabei, diesen Angriff zurückzuschlagen!\n\nIch werde versuchen, den Kriegshäuptling abzufangen. Es wird unsere letzte Chance sein, sie aufzuhalten. Erstattet Kommandantin Sommermond während meiner Abwesenheit Bericht.", sourceObjective = "Schaltet die Streitkräfte der Horde in Lor'danel aus.", completion = "Eure Hilfe ist willkommen, aber ich fürchte, die Horde ist nicht aufzuhalten. Es kommen immer mehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[53623] = { id = 53623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle for Azeroth Dungeon Reward Quest" }
quests[53627] = { id = 53627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk aus Azerit", description = "Ich glaube, wir haben hier jetzt alles im Griff. Ihr müsst dieses ganze Azerit zurück zu Zarvik Bummfix ins Hauptlager bringen!\n\nEr wird schon wissen, wie wir dieses Zeug am besten einsetzen können, um die Allianz zu besiegen.", sourceObjective = "Bringt Azerit zu Zarvik Bummfix im Bau der Schwarzfelle.", completion = "Azerit?! Für mich?! Das wäre doch nicht nötig gewesen!\n\nKleiner Scherz. Natürlich war es das.", sourceObjectiveStatus = "unverified-source-field" }
quests[53641] = { id = 53641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - BFA - Stromgarde (Arathi)" }
quests[53665] = { id = 53665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bereit zur Schlacht", description = "Seid gegrüßt, {name}.\n\nUnsere Rekruten brennen darauf, Euch im Kampf zu unterstützen.", sourceObjective = "Sprecht mit Throk, um einen Verbündeten aus der Kaserne zu rekrutieren.", progress = "Sucht Ihr nach Rekruten?", completion = "Mit unseren Verbündeten an Eurer Seite werden wir das Schlachtfeld beherrschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53666] = { id = 53666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wettrüsten", description = "Ah, {name}. Neuigkeiten verbreiten sich hier schnell.\n\nJetzt, wo all die Aufträge eingehen, habe ich leider nicht viel Zeit zu reden.\n\nWenn Ihr mehr über das Arsenal wissen wollt, kann Fennick Euch damit helfen. Er ist draußen.", sourceObjective = "Sprecht mit Fennick, um zu erfahren, was das Arsenal zu bieten hat.", completion = "Was? Drom'kal hat keine Zeit für Euch? Das wundert mich nicht.\n\nNaja, zumindest ist das Arsenal bereit und wir können daran arbeiten, unseren Verbündeten bessere Ausrüstung bereitzustellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53667] = { id = 53667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen in der Werkstatt", description = "Ihr müsst <der neue Typ/das neue Mädel> sein. Ich bin Margie, das da drüben ist Pixy.\n\nWir verstehen uns hier in der Werkstatt auf unser Handwerk. Wenn Ihr mal irgendwas braucht, wisst Ihr ja, wo Ihr uns findet.\n\nAm besten geht Ihr gleich rüber und redet mit Pixy. Sie kann Euch zeigen, was so eine Werkstatt kann.", sourceObjective = "Sprecht mit Pixy Schlüsselschraub, um zu erfahren, was die Werkstatt zu bieten hat.", completion = "Das war ja schnell!\n\nWie gesagt, wenn Ihr irgendwas braucht, wisst Ihr, wo Ihr uns findet.", sourceObjectiveStatus = "unverified-source-field" }
quests[53668] = { id = 53668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Netzwerk des Fluggenieurs", description = "Jetzt, wo wir den Hochstand kontrollieren, beherrschen wir auch die Lüfte!\n\nIch habe in dieser Notiz ein paar Pläne zur Erweiterung unseres Flugnetzwerks ausgearbeitet. Wärt Ihr so freundlich, sie unserem Kommandanten zu bringen? Der Kommandant wird sich bestimmt über unsere Fortschritte freuen.\n\nSagt mir, wenn Ihr bereit seid, dann schicke ich Euch los.", sourceObjective = "Bringt die Notiz von Fluggenieur Krazzel Eurem Kommandanten in Ar'gorok.", completion = "Unser Goblinfreund versichert mir, dass er unser Transportnetzwerk ausbauen kann, solange wir bestimmte Schlüsselpositionen halten.\n\nDann wissen wir ja, was wir zu tun haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[53669] = { id = 53669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht des Altars", description = "Es sieht so aus, als sind die Bauarbeiten am Altar der Stürme abgeschlossen.\n\nIch bin mir sicher, Meredith würde sich freuen, Euch die mysteriösen Kräfte zu zeigen, die in ihm schlummern.", sourceObjective = "Sprecht mit Meredith der Greisin, um zu erfahren, was der Altar der Stürme zu bieten hat.", completion = "Ha. Schau mal einer an.\n\nIch kann seine Energie sogar von hier fühlen!", sourceObjectiveStatus = "unverified-source-field" }
quests[53670] = { id = 53670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die wilden Tiere von Neuhof", description = "Nichts durchbricht die Frontlinie des Feindes wie ein wilder Reiter auf einem gut ausgebildeten Tier. Seitdem wir Neuhof kontrollieren, hat sich besonders einer unserer Reiter darauf konzentriert, uns ein paar Kodos heranzuziehen.\n\nGeht, unterhaltet Euch mal mit Tanauk und findet heraus, wozu diese Tiere fähig sind.", sourceObjective = "Sprecht mit Kodoreiter Tanauk, um mehr über die Tiere zu erfahren, die er ausbildet.", completion = "Mächtige Tiere, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[53671] = { id = 53671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht des Zirkels", description = "Durch die Einnahme des Zirkels der Elemente bietet sich uns die Möglichkeit, uns die Macht der Elemente zunutze zu machen.\n\nKraga versteht diese Macht sehr gut. Ich rate Euch, mit ihr zu reden.", sourceObjective = "Sprecht mit Kraga Gezeitenzorn, um zu erfahren, was sie Euch zu bieten hat.", progress = "Habt Ihr gefunden, was Ihr gesucht habt?", completion = "Solche Macht sollte man nicht unterschätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[53672] = { id = 53672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bereit zur Schlacht", description = "Willkommen an der Kriegsfront, {name}.\n\nUnsere Rekruten brennen darauf, Euch im Kampf zu unterstützen.\n\nSprecht erst einmal mit Ralston. Ich bin sicher, er hat ein paar Soldaten, die an Eurer Seite im Kampf vieles lernen könnten.", sourceObjective = "Sprecht mit Ralston Karn, um einen Verbündeten aus der Kaserne zu rekrutieren.", progress = "Sucht Ihr nach Rekruten?", completion = "Mit unseren Verbündeten an Eurer Seite habe ich keine Zweifel, dass wir die Hordebedrohung aus Arathi vertreiben werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[53673] = { id = 53673, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wettrüsten", description = "Was haben wir denn da? <Ein frischer, junger Bursche/Eine frische> junge Dame;, voller Tatendrang und bereit, unsere Verbündeten auf die Schlacht vorzubereiten? Nun denn, Jonathan kann immer Leute gebrauchen, die ihm helfen, das Arsenal am Laufen zu halten.\n\nIch würde Euch ja begleiten, aber ich habe hier alle Hände voll zu tun. Ihr findet ihn da drüben.", sourceObjective = "Sprecht mit Jonathan Flynn, um zu erfahren, was das Arsenal zu bieten hat.", completion = "Hmm? Ah, ja.\n\nIst alles in Ordnung? Wir haben ausreichend Arsenalressourcen, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[53674] = { id = 53674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht des Altars", description = "Wir haben gerade einige Ressourcen erhalten, da ist es keine Überraschung, dass der Altar der Könige so schnell aus dem Boden gestampft wurde.\n\nIch würde Euch empfehlen, mal dort vorbeizuschauen. Ihr werdet überrascht sein, was der Altar alles zu bieten hat.", sourceObjective = "Sprecht mit Altarit Jesse Taylor, um zu erfahren, was der Altar der Könige zu bieten hat.", completion = "Ach du meine Güte! Was für eine unglaubliche Energiequelle.", sourceObjectiveStatus = "unverified-source-field" }
quests[53675] = { id = 53675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen in der Werkstatt", description = "Willkommen in der Werkstatt!\n\nIch wollte Murrer unnötige Ablenkungen eigentlich ersparen, aber vielleicht wäre es für uns alle hilfreich, wenn Ihr Euch unsere Arbeit mal anseht.\n\nGeht ruhig zu ihm rüber und seht Euch an, was wir hier machen.", sourceObjective = "Sprecht mit Murrer, um zu erfahren, was die Werkstatt zu bieten hat.", completion = "Ah, wunderbar. Ihr habt also einen kleinen Einblick in unsere Arbeit erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[53676] = { id = 53676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht des Zirkels", description = "Mit dem Zirkel der Elemente in unserer Hand bietet sich uns nun die Möglichkeit, seine große Macht anzuzapfen. Justinia, eine unserer Verbündeten, verfügt über das Wissen darüber, was das für unsere Kriegsanstrengungen bedeuten könnte.\n\nSucht sie auf. Es ist an der Zeit, dass Ihr Euch mit der Macht der Elemente vertraut macht.", sourceObjective = "Sprecht mit Justinia Frost, um zu erfahren, was sie Euch zu bieten hat.", progress = "Habt Ihr etwas herausgefunden?", completion = "Unser Feind hat kaum eine Chance.", sourceObjectiveStatus = "unverified-source-field" }
quests[53677] = { id = 53677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die wilden Tiere von Neuhof", description = "Durch die Einnahme Neuhofs waren unsere Truppen in der Lage, weiter vorzurücken. Darüber hinaus hat Verteidiger Banra nun mehr als genug Platz, um das Kampftraining seiner Elekks fortzusetzen.\n\nIch empfehle Euch, mit ihm zu reden, um mehr darüber zu erfahren, wozu diese prachtvollen Tiere so alles fähig sind.", sourceObjective = "Sprecht mit Verteidiger Banra, um mehr über die Tiere zu erfahren, die er ausbildet.", progress = "Bleibt wachsam.", completion = "Prachtvolle Tiere. Findet Ihr nicht auch?", sourceObjectiveStatus = "unverified-source-field" }
quests[53678] = { id = 53678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höhenflug", description = "Jetzt, wo wir den Hochstand kontrollieren, haben wir auch in der Luft die Oberhand!\n\nIch habe Pläne für ein Flugnetzwerk entworfen, das unseren Verbündeten sichere Flüge garantieren würde. Bitte nehmt diese Notizen und bringt sie sofort unserem Kommandanten.\n\nIch stelle Euch gerne einen Greifen zur Verfügung, der Euch zur Basis fliegen kann, sobald Ihr so weit seid.", sourceObjective = "Bringt Graysons Notiz Eurem Kommandanten in Burg Stromgarde.", completion = "Ausgezeichnete Neuigkeiten. Wenn wir strategische Schlachtfeldpositionen kontrollieren, können unsere Greifen ohne Hindernisse an verschiedene Orte fliegen.\n\nWir müssen unsere Anstrengungen noch weiter verstärken.", sourceObjectiveStatus = "unverified-source-field" }
quests[53699] = { id = 53699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torknacker" }
quests[53701] = { id = 53701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drustsache", description = "Armeen der Horde dringen ins Herz von Drustvar vor. Haltet die Stellung und jagt sie wieder in die Löcher zurück, aus denen sie gekrochen sind. Kul Tiras gehört uns!", sourceObjective = "Schlagt die Streitkräfte der Horde zurück, die Drustvar angreifen.", completion = "Die Horde hat bekommen, was sie verdient hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[53704] = { id = 53704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht allzu nüchterne Bürgerwehr" }
