quests[53707] = { id = 53707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Räuchert die Vorräte" }
quests[53711] = { id = 53711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesunde Verteidigung", description = "Streitkräfte der Horde attackieren den Tiragardesund. Lasst sie jeden Schritt bereuen, den sie auf unser Land tun!", sourceObjective = "Schlagt die Streitkräfte der Horde zurück, die den Tiragardesund angreifen.", completion = "Alle in Boralus sind in Jubel ausgebrochen, als wir die Explosionen auf dem Luftschiff gesehen haben! Die Horde wird es sich zweimal überlegen, bevor sie Boralus erneut angreift.", sourceObjectiveStatus = "unverified-source-field" }
